className:
p-2.5 rounded-xl transition-all flex items-center justify-center flex-shrink-0 shadow-sm ${
                input.trim()
                  ? "bg-brand-900 hover:bg-brand-800 text-white shadow-md cursor-pointer scale-105"
                  : "bg-slate-100 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 cursor-not-allowed opacity-90"
              }

btn-primary text-sm flex items-center gap-1.5 ${
                    mode === "verify" && !matchResult?.verified
                      ? "opacity-50 cursor-not-allowed"
                      : ""
                  }

flex items-center gap-2 px-3 py-2 rounded-lg transition-colors ${
            isActive
              ? "bg-blue-100 text-blue-700 font-medium"
              : "hover:bg-slate-100 text-slate-700"
          }

block px-3 py-1 rounded text-sm transition-colors ${
                  location.pathname === child.path
                    ? "bg-blue-50 text-blue-600 font-medium"
                    : "hover:bg-slate-50 text-slate-600"
                }

px-5 py-3 rounded-xl transition-all flex items-center justify-center gap-1.5 text-xs flex-shrink-0 shadow-sm ${
                  input.trim()
                    ? "bg-brand-900 hover:bg-brand-800 text-white shadow-md cursor-pointer scale-105"
                    : "bg-slate-100 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 cursor-not-allowed opacity-90"
                }

w-6 h-6 rounded-full flex items-center justify-center shrink-0 transition-colors ${
                              item.completed
                                ? "bg-emerald-500 text-white"
                                : "border-2 border-slate-300 dark:border-slate-600 text-transparent hover:border-emerald-500"
                            }

text-xs px-2.5 py-1 rounded border transition-colors cursor-pointer ${
                              r.is_active
                                ? "border-rose-200 text-rose-600 hover:bg-rose-50 dark:border-rose-800 dark:hover:bg-rose-950/30"
                                : "border-slate-300 text-slate-600 hover:bg-slate-100 dark:border-slate-600 dark:hover:bg-slate-800"
                            }

pb-3 px-1 text-sm font-semibold transition-colors border-b-2 ${
            tab === "request"
              ? "border-brand text-brand"
              : "border-transparent text-slate-500 hover:text-slate-800 dark:hover:text-slate-200"
          }

pb-3 px-1 text-sm font-semibold transition-colors border-b-2 ${
            tab === "schedule"
              ? "border-brand text-brand"
              : "border-transparent text-slate-500 hover:text-slate-800 dark:hover:text-slate-200"
          }

px-3 py-1 text-xs font-semibold rounded-md transition-colors ${
                  viewType === "chart"
                    ? "bg-brand text-white shadow"
                    : "text-slate-600 dark:text-slate-400 hover:text-slate-900"
                }

px-3 py-1 text-xs font-semibold rounded-md transition-colors ${
                  viewType === "gantt"
                    ? "bg-brand text-white shadow"
                    : "text-slate-600 dark:text-slate-400 hover:text-slate-900"
                }

px-5 py-2.5 font-bold text-sm border-b-2 transition-all ${
                  activeTab === "detailed"
                    ? "border-brand text-brand"
                    : "border-transparent text-slate-400 hover:text-slate-600"
                }

px-5 py-2.5 font-bold text-sm border-b-2 transition-all ${
                  activeTab === "summary"
                    ? "border-brand text-brand"
                    : "border-transparent text-slate-400 hover:text-slate-600"
                }

px-4 py-2.5 text-sm font-medium border-b-2 transition-colors ${
        active
          ? "border-blue-500 text-blue-600 dark:text-blue-400"
          : "border-transparent text-slate-500 hover:text-slate-700 dark:hover:text-slate-300"
      }

text-xs px-3 py-1.5 rounded-lg font-semibold text-white flex items-center gap-1 ${
                      action === "APPROVE" ? "bg-emerald-600 hover:bg-emerald-700" :
                      action === "REJECT" ? "bg-red-600 hover:bg-red-700" :
                      "bg-amber-500 hover:bg-amber-600"
                    }

text-sm px-4 py-2 rounded-lg font-semibold text-white flex items-center gap-1.5 ${
              action === "APPROVE" ? "bg-emerald-600 hover:bg-emerald-700" : "bg-red-600 hover:bg-red-700"
            }

px-4 py-2 rounded-md border ${
      active
        ? "bg-slate-100 border-slate-300 text-slate-900"
        : "bg-white border-slate-200 text-slate-600"
    }

block w-full text-left px-3.5 py-2 text-xs transition-colors hover:bg-slate-50 dark:hover:bg-slate-800 ${
                          String(clientForm.sales_account_id) === o.value
                            ? "bg-brand-50 text-brand-900 dark:bg-brand-950/40 dark:text-brand-300 font-bold"
                            : "text-slate-700 dark:text-slate-300"
                        }

w-6 h-6 rounded-full flex items-center justify-center shrink-0 transition-colors ${
                              item.completed
                                ? "bg-emerald-500 text-white"
                                : "border-2 border-slate-300 dark:border-slate-600 text-transparent hover:border-emerald-500"
                            }

px-5 py-2.5 rounded text-sm font-semibold transition-all ${
                formData.po_type === "IMPORT"
                  ? "bg-[#0E3646] text-white"
                  : "text-gray-500 hover:bg-gray-200"
              }

px-5 py-2.5 rounded text-sm font-semibold transition-all ${
                formData.po_type === "LOCAL"
                  ? "bg-[#0E3646] text-white"
                  : "text-gray-500 hover:bg-gray-200"
              }

w-full inline-flex items-center justify-center px-4 py-1.5 text-sm font-medium text-slate-700 bg-slate-100 border border-slate-200 rounded-lg hover:bg-slate-200 transition-colors h-9 ${
                              !canPerformAction(
                                "purchase:supplier-quotations",
                                "view",
                              )
                                ? "invisible pointer-events-none"
                                : ""
                            }

w-full inline-flex items-center justify-center px-4 py-1.5 text-sm font-medium text-slate-700 bg-slate-100 border border-slate-200 rounded-lg hover:bg-slate-200 transition-colors h-9 ${
                              !canPerformAction(
                                "purchase:supplier-quotations",
                                "edit",
                              )
                                ? "invisible pointer-events-none"
                                : ""
                            }

w-full inline-flex items-center justify-center px-4 py-1.5 text-sm font-medium text-slate-700 bg-slate-100 border border-slate-200 rounded-lg hover:bg-slate-200 transition-colors h-9 ${
                              !canPerformAction(
                                "sales:customers",
                                "edit",
                              )
                                ? "invisible pointer-events-none"
                                : ""
                            }

w-full inline-flex items-center justify-center px-4 py-1.5 text-sm font-medium text-slate-700 bg-slate-100 border border-slate-200 rounded-lg hover:bg-slate-200 transition-colors h-9 ${
                                !canPerformAction("sales:delivery", "view")
                                  ? "invisible pointer-events-none"
                                  : ""
                              }

w-full inline-flex items-center justify-center px-4 py-1.5 text-sm font-medium text-slate-700 bg-slate-100 border border-slate-200 rounded-lg hover:bg-slate-200 transition-colors h-9 ${
                              !canPerformAction(
                                "sales:potential-customers",
                                "edit",
                              )
                                ? "invisible pointer-events-none"
                                : ""
                            }

w-full inline-flex items-center justify-center px-4 py-1.5 text-sm font-medium text-slate-700 bg-slate-100 border border-red-200 text-red-700 rounded-lg hover:bg-red-50 transition-colors h-9 ${
                              !canPerformAction(
                                "sales:potential-customers",
                                "delete",
                              )
                                ? "invisible pointer-events-none"
                                : ""
                            }

p-4 rounded-lg border-2 text-left transition ${
                activeTab === "internal"
                  ? "border-brand-500 bg-brand-50 dark:bg-brand-900/20"
                  : "border-slate-200 hover:border-brand-300 dark:border-slate-700"
              }

p-4 rounded-lg border-2 text-left transition ${
                activeTab === "external"
                  ? "border-brand-500 bg-brand-50 dark:bg-brand-900/20"
                  : "border-slate-200 hover:border-brand-300 dark:border-slate-700"
              }

group card hover:shadow-xl transition-all duration-300 bg-white dark:bg-slate-900 border rounded-2xl p-6 flex flex-col justify-between ${
              report.isFeatured
                ? "border-purple-200 dark:border-purple-900/60 ring-2 ring-purple-500/20 dark:ring-purple-500/40"
                : "border-slate-200 dark:border-slate-800 hover:border-indigo-300 dark:hover:border-indigo-800"
            }

flex flex-col items-center justify-center py-1 px-3 rounded-xl transition-all duration-150 ${
                  active
                    ? "text-teal-400 font-semibold scale-105"
                    : "text-slate-400 hover:text-slate-200 font-normal"
                }
